window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"AKOpOmTYO3s","speaker":"Lamine Zeine Ali Mahaman","role":"Prime Minister","country":"Niger","region":"Africa","url":"https://www.youtube.com/watch?v=AKOpOmTYO3s","date":"20260925","title":"🇳🇪 Niger - Prime Minister Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1676,"words":3155,"counts":{"claims":50,"promises":2,"attacks":4},"topics":[{"topic":"Niger sovereignty","share":0.1347,"seconds":226},{"topic":"Niger uranium","share":0.1338,"seconds":224},{"topic":"Niger security","share":0.1222,"seconds":205},{"topic":"Sahel conflict","share":0.0811,"seconds":136},{"topic":"AES","share":0.0798,"seconds":134},{"topic":"Niger development","share":0.0539,"seconds":90},{"topic":"Sahel sovereignty","share":0.0519,"seconds":87},{"topic":"Niger economy","share":0.0462,"seconds":77},{"topic":"UN trust","share":0.0453,"seconds":76},{"topic":"Niger resilience","share":0.0434,"seconds":73},{"topic":"Mali","share":0.0429,"seconds":72},{"topic":"Sovereign equality","share":0.0404,"seconds":68},{"topic":"Palestine","share":0.0373,"seconds":63},{"topic":"Niger diplomacy","share":0.0363,"seconds":61},{"topic":"Sahel integration","share":0.0361,"seconds":60},{"topic":"Sahel states","share":0.0146,"seconds":24}],"timeline":[[1,66,null],[67,128,"Niger diplomacy"],[130,206,"UN trust"],[207,294,"Sahel sovereignty"],[296,359,"Palestine"],[364,435,"Sahel conflict"],[436,517,"Niger uranium"],[519,584,"Sahel conflict"],[589,657,"Niger security"],[659,727,"AES"],[729,805,"Niger sovereignty"],[806,878,"Mali"],[879,940,"Sahel integration"],[940,1005,"AES"],[1006,1093,"Niger sovereignty"],[1094,1157,"Niger security"],[1159,1233,"Niger security"],[1235,1299,"Niger uranium"],[1300,1379,"Niger uranium"],[1383,1460,"Niger economy"],[1461,1552,"Niger development"],[1552,1625,"Niger resilience"],[1626,1695,null],[1696,1759,"Niger sovereignty"],[1761,1829,"Sovereign equality"],[1830,1854,"Sahel states"]],"stances":{"Niger diplomacy":"Lamine Zeine Ali Mahaman delivers formal greetings and congratulations on behalf of the President and people of Niger to the new General Assembly President, the predecessor, and the Secretary-General.","UN trust":"Lamine Zeine Ali Mahaman argues that restoring trust in the United Nations requires effective implementation of promises rather than making new ones.","Sahel sovereignty":"Lamine Zeine Ali Mahaman argues that trust must be built on truth and justice because international institutions have become tools of an unequal world order where crimes in the Sahel and other regions go unpunished while sovereign nations face sanctions for choosing their own fate.","Palestine":"Lamine Zeine Ali Mahaman expresses deep concern over the civilian cost in Gaza, calls for protection and humanitarian access, reaffirms support for a two-state solution, and highlights Africa's lack of representation on the Security Council.","Sahel conflict":"Lamine Zeine Ali Mahaman asserts that the conflict in the Sahel is a war of liberation against a conspiracy to recolonize the region driven by resource covetousness rather than terrorism or internal weakness.","Niger uranium":"Lamine Zeine Ali Mahaman argues that former colonial powers seek to exploit Niger's natural resources and undermine its sovereignty by promoting narratives of incapacity and imposing tutelage.","Niger security":"Lamine Zeine Ali Mahaman asserts that proxies supported by France, Ukraine, and other unnamed countries are preparing to attack Niger's military and oil installations, while affirming the irreversible sovereignty of the AES alliance.","AES":"Lamine Zeine Ali Mahaman describes the Alliance of Sahel States (AES) as a historic movement bringing hope and dignity to Africa, resulting from the abolition of slavery and colonialism, and asserts that its foundation in Niamey is not targeted against anyone.","Niger sovereignty":"Lamine Zeine Ali Mahaman asserts that Niger's sovereignty and resource control are non-negotiable and that the country must manage its own destiny without external interference.","Mali":"The speaker honors the late Malian Minister of Defense and states openness to security cooperation with Mali and Burkina Faso based on mutual interests and sovereignty.","Sahel integration":"Lamine Zeine Ali Mahaman states that the Sahel confederation has been established with a nearly complete institutional structure and a unified military force.","Niger economy":"Lamine Zeine Ali Mahaman states that Niger has achieved remarkable economic progress, including 7% growth and reduced inflation, following a break with the old order.","Niger development":"Lamine Zeine Ali Mahaman reports that Niger has achieved satisfactory results in food security, health, and education through specific government programs.","Niger resilience":"Lamine Zeine Ali Mahaman states that Niger has not collapsed under sanctions due to the resilience of its people and support from regional partners.","Sovereign equality":"Lamine Zeine Ali Mahaman asserts that trust among nations can only be restored when the right to sovereign equality and territorial integrity is respected for all countries regardless of size.","Sahel states":"Lamine Zeine Ali Mahaman expresses support for international cooperation and the Confederation of Sahel States while thanking the assembly."},"claims":[{"t":76,"quote":"On behalf of his excellency the general of the army Abdul Rahman Tiani, President of the Republic of Nijer","topic":"Niger diplomacy","kind":"fact"},{"t":119,"quote":"Mr. Antonio Guteres, Secretary General of our organization, whose second term will conclude on the 31st of December","topic":"Niger diplomacy","kind":"fact"},{"t":149,"quote":"bombs and other devices of mass destruction are endlessly causing death and devastation in every corner of our planet","topic":"UN trust","kind":"fact"},{"t":222,"quote":"for decades propaganda has been used to maintain the idea of a poor Africa condemned to do everything it is told to do to survive thanks to the assistance of supposed international generosity even while its resources its riches are stolen and locked away for the benefit of other agendas","topic":"Sahel sovereignty","kind":"fact"},{"t":250,"quote":"the international institutions that are supposed to protect us have become the tools of a world order in which some people's count and others merely survive and in which international law does not apply equally to all","topic":"Sahel sovereignty","kind":"fact"},{"t":268,"quote":"What can we say of the crimes committed in Libya, in Iraq, in Palestine, in Lebanon, in Cuba, in Venezuela, uh, and in our Sahel, the Sahel, in the name of supposedly universal values, which nevertheless remain unpunished","topic":"Sahel sovereignty","kind":"fact"},{"t":307,"quote":"civilians are paying an unbearable human cost","topic":"Palestine","kind":"fact"},{"t":344,"quote":"81 years after San Francisco, Africa with its more than uh around one and a half billion inhabitants and its 54 states still does not have a single permanent seat on the security council","topic":"Palestine","kind":"fact"},{"t":386,"quote":"our Sahel is at war. It is in a war of liberation against a conspiracy aimed at recolonizing it.","topic":"Sahel conflict","kind":"fact"},{"t":407,"quote":"What some call terrorism in our region is the cynical machinery of dressed in the trappings of extremism.","topic":"Sahel conflict","kind":"fact"},{"t":436,"quote":"Nijair's uranium, Marley and Bkina Faso's gold, lithium, gas, oil and so many other riches still make the former colonial powers salivate.","topic":"Niger uranium","kind":"fact"},{"t":498,"quote":"they continue to want to introduce produce permanent conflict in communities which since time immemorial have been living in harmony in the same space","topic":"Niger uranium","kind":"fact"},{"t":519,"quote":"This perfidious attempt to destabilize the central Sahel conducted by France with the active complicity of Ukraine is now documented widely documented.","topic":"Sahel conflict","kind":"fact"},{"t":533,"quote":"This criminal enterprise has been dismass has been unmasked now that the military, political and media elites that justify it in the name of their own country's interests have themselves removed their veils and and removed their masks.","topic":"Sahel conflict","kind":"fact"},{"t":598,"quote":"proxies led by that France supported by Ukraine and two other And You know which countries I'm alluding to. Those proxies are armed, managed, and led and they are about to attack our military positions and our oil installations.","topic":"Niger security","kind":"fact"},{"t":679,"quote":"The AES is the result of a movement that dates from the dawn of time. It is a profound, lasting, irrepressible and irreversible change.","topic":"AES","kind":"fact"},{"t":697,"quote":"A change which by trimming the sharp claws of imperialism, abolishing the trade in black persons and slavery, overthrowing colonialism and is bringing the peoples of Africa towards independence, sovereignty","topic":"AES","kind":"fact"},{"t":740,"quote":"The head of state, President Tiani, has consistently said this.","topic":"Niger sovereignty","kind":"fact"},{"t":751,"quote":"We have never been driven out of a desire to trouble anyone else.","topic":"Niger sovereignty","kind":"fact"},{"t":879,"quote":"On the 16th of September 2023 in Bamako, Nijair Mali Ambakina Faso signed the Liptako Gurma Charter giving birth to the alliance of Sahel states.","topic":"Sahel integration","kind":"fact"},{"t":893,"quote":"On the 6th of July 2024 in Yame, our three heads of state, President Aimua of Mali, President Ibrahim Trare of and President Abdul Rahman Tani of Nijair took the historic step of creating the confederation of Sahil Two years later, the institutional structure of this confederation is practically complete.","topic":"Sahel integration","kind":"fact"},{"t":922,"quote":"A unified force of 5,000 men is conducting the coordinated fight against the mercenaries afflicting our three uh on our borders.","topic":"Sahel integration","kind":"number"},{"t":935,"quote":"This force can be mobilized to a ceiling of 15,000 men.","topic":"Sahel integration","kind":"number"},{"t":944,"quote":"A confederation investment and the development bank has been created. It finance our finances our projects and programs using our own resources.","topic":"AES","kind":"fact"},{"t":955,"quote":"A confederation biometric passport has been in use since the 29th of January 2020 uh five.","topic":"AES","kind":"number"},{"t":972,"quote":"from the 26th to the 29th of August the first meetings of the Confederation Parliament were held in Yam","topic":"AES","kind":"fact"},{"t":1027,"quote":"Since the 26th of July 2023, Nijair has been continuing its inexurable march towards the total reconquest of its sovereignty under the leadership of the National Council for the Safeguarding of the Homeland by the President His Excellency the General of the Army Abdul Rahman Tiani, President of the Republic, head of state.","topic":"Niger sovereignty","kind":"fact"},{"t":1089,"quote":"revenue which previously the state did not have control over","topic":"Niger sovereignty","kind":"fact"},{"t":1096,"quote":"a few days ago in the night from the 28th to the 29th of August 2026, after two previous fruitless attempts to attack Ji Hamani International Airport in Yame, a third attempt, which General Tiani said, a third attempt at destabilization led by obscurantist and colonialist forces targeted our institution.","topic":"Niger security","kind":"fact"},{"t":1127,"quote":"As in the previous cases, it failed. It thanks to the loyalty of our forces, of our defense and security forces and the loyalty of our armed forces.","topic":"Niger security","kind":"fact"},{"t":1159,"quote":"The necessary investigations are underway in order to establish the circumstances, who is responsible, and the internal and external support linked to this attempt.","topic":"Niger security","kind":"fact"},{"t":1237,"quote":"for more than half a century, uranium, this this miraculous substance, Nijes uranium has lit the cities of Europe while our cities have remained in darkness.","topic":"Niger uranium","kind":"fact"},{"t":1258,"quote":"In June 2025, the state of Nijair recovered control of Somaya, the assoc associated delayer.","topic":"Niger uranium","kind":"fact"},{"t":1304,"quote":"Nijair has invested some 30 billion of our franks to continue that production. totally making use of nisharian workers and experts. Not a single foreigner was involved in that.","topic":"Niger uranium","kind":"number"},{"t":1344,"quote":"Similarly, in 2024, our country became a an exporter of crude oil thanks to the oil pipeline linking Agadem to the Atlantic coast along the African cont the the longest one in the African continent making nijair one of the continent's fastest growing economies","topic":"Niger uranium","kind":"fact"},{"t":1407,"quote":"Our economy has seen 7% growth in 2026 in 2025, excuse me, driven above all by oil and agriculture.","topic":"Niger economy","kind":"number"},{"t":1418,"quote":"Inflation, which reached 9.1% in 2024, has fallen to thanks uh to exceptional agricultural production and a targeted reduction of fuel and cement prices.","topic":"Niger economy","kind":"number"},{"t":1442,"quote":"The large scale irrigation program initiated by the president of the republic has 527 billion CFA franks and aims to ensure that around 22,000 hectares uh of new irrigated land can be established.","topic":"Niger economy","kind":"number"},{"t":1464,"quote":"for the first time in decades, our country has not faced food shortages or had to call upon foreign assistance.","topic":"Niger development","kind":"fact"},{"t":1474,"quote":"we intend to have our grain imports by the end of 2027.","topic":"Niger development","kind":"number"},{"t":1485,"quote":"on health we have reduced by 50% the cost of services in public health facilities.","topic":"Niger development","kind":"number"},{"t":1500,"quote":"The assisted birth rate went from 36% in 2022 to 42.5% in 2025.","topic":"Niger development","kind":"number"},{"t":1508,"quote":"the rate of prenatal consultations went from 38% uh to it went from 32% to 38.2%.","topic":"Niger development","kind":"number"},{"t":1560,"quote":"three years ago, some people predicted that Nijer would collapse under the weight of sanctions and isolation. Today, Nijair is standing It is standing tall because its people has refused to bow down.","topic":"Niger resilience","kind":"fact"},{"t":1577,"quote":"within the confederation of Sahel states, it has found a family, solidarity, and a family in the full African meaning of the term.","topic":"Niger resilience","kind":"fact"},{"t":1590,"quote":"the People's Democratic Republic of Algeria, a kindred and neighboring country, chose to support us with a substantial investment in the exploitation of our natural resources and through constant support for our defense system","topic":"Niger resilience","kind":"fact"},{"t":1619,"quote":"significant structural projects such as the tripartite gas pipeline and the transahara road.","topic":"Niger resilience","kind":"fact"},{"t":1720,"quote":"We are convinced that no country, however powerful it may be, can claim to be the world's policeman.","topic":"Niger sovereignty","kind":"fact"},{"t":1746,"quote":"Nija intends to fully exercise its sovereignty over its natural resources and will never again accept any restriction imposed from outside on its sovereign right to freely choose its partners.","topic":"Niger sovereignty","kind":"fact"},{"t":1761,"quote":"That right is inalienable and it is non-negotiable. We declare that trust will be reborn when every nation big or small is treated with the same consideration.","topic":"Sovereign equality","kind":"fact"}],"promises":[{"t":1268,"quote":"Our resources will now be managed by us and for us and Nijair intends to sell its uranium on the international market in full transparency and in strict compliance with its nuclear non-prololiferation obligations.","topic":"Niger uranium","kind":"promise"},{"t":1746,"quote":"Nija intends to fully exercise its sovereignty over its natural resources and will never again accept any restriction imposed from outside on its sovereign right to freely choose its partners.","topic":"Niger sovereignty","kind":"promise"}],"attacks":[{"t":251,"quote":"international institutions that are supposed to protect us have become the tools of a world order in which some people's count and others merely survive and in which international law does not apply equally to all","topic":"Sahel sovereignty","target":"International Institutions"},{"t":476,"quote":"tutilage of Emanuel Macron's France and his allies a France which very often acts through its local proxies networks and complicity","topic":"Niger uranium","target":"France"},{"t":519,"quote":"This perfidious attempt to destabilize the central Sahel conducted by France with the active complicity of Ukraine","topic":"Sahel conflict","target":"France"},{"t":598,"quote":"proxies led by that France supported by Ukraine and two other And You know which countries I'm alluding to.","topic":"Niger security","target":"France"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":1,"topic":null,"text":"The assembly will hear an address by his excellency Lamin Zen Ali Mahm, Prime Minister of the Republic of Nijair. I request protocol to escort his excellency and invite him to address the Mr. Mr. President of the General Assembly, Mr. Secretary General, ladies and gentlemen, heads of state and Ladies and gentlemen, heads of delegation."},{"t":67,"topic":"Niger diplomacy","text":"Ladies and gentlemen, I am taking the floor before this August on behalf of my country. On behalf of his excellency the general of the army Abdul Rahman Tiani, President of the Republic of Nijer, a head of state to express the message of peace of the people of Nijer, the sovereign people of Nijair, a people that is committed to its dignity and to cooperation among nations. Mr. President, please accept the congratulations of Nishair upon your election to the presidency of this 81st session of the General Assembly as well as our thanks to your predecessor, her excellency, Miss Anelena Berbok, and Mr. Antonio Guteres, Secretary General of our organization, whose second term will conclude on the 31st of December."},{"t":130,"topic":"UN trust","text":"Mr. President, the theme of this session, restoring trust, managing a united nations that delivers for all, perfectly triumphs with the concerns of those peoples aspiring to peace and progress, even while bombs and other devices of mass destruction are endlessly causing death and devastation in every corner of our planet. How can we restore trust and manage transformation in the world so that the United Nations can effectively bring peace and good fortune to all peoples? How then can we achieve this goal? I would recall that our previous session called upon us to act better together. That message remains just and it remains relevant. But it requires us to take to look at what has been accomplished and to acknowledge what has not been accomplished because trust is not built through more and more promises but rather through their effective implementation for the benefit of the peoples."},{"t":207,"topic":"Sahel sovereignty","text":"Excellencies, ladies and gentlemen, trust cannot be decreed. It is built. It is earned. And it requires truth and justice. How to restore trust when for decades propaganda has been used to maintain the idea of a poor Africa condemned to do everything it is told to do to survive thanks to the assistance of supposed international generosity even while its resources its riches are stolen and locked away for the benefit of other agendas. How to restore this trust when the international institutions that are supposed to protect us have become the tools of a world order in which some people's count and others merely survive and in which international law does not apply equally to all. What can we say of the crimes committed in Libya, in Iraq, in Palestine, in Lebanon, in Cuba, in Venezuela, uh, and in our Sahel, the Sahel, in the name of supposedly universal values, which nevertheless remain unpunished, those crimes, even while sovereign nations are threatened with sanctions for simply having wanted to decide on their own fate."},{"t":296,"topic":"Palestine","text":"Nijair, my country is following with deep concern the tragic situation in Palestine, particularly in Gaza, where civilians are paying an unbearable human cost. We call for the effective protection of civilian populations, for unhindered humanitarian access, and for the pursuit of just and lasting peace. Nijair reaffirms its support for a two-state allowing the state of Palestine and the state of Israel to live side by side in peace, security, and dignity. How to restore trust when 81 years after San Francisco, Africa with its more than uh around one and a half billion inhabitants and its 54 states still does not have a single permanent seat on the security council."},{"t":364,"topic":"Sahel conflict","text":"Through me, Nishair reaffirms its commitment to the Ezelini consensus and calls for this historic anomaly to no longer be the subject of sterile debates repeated day after day to at long last become subject to a full and concrete Excellencies, Mr. President, ladies and gentlemen, our Sahel is at war. It is in a war of liberation against a conspiracy aimed at recolonizing it. What is happening in the Sahel is not merely not simply an armed rebellion or a war of religion. Nor is it the inevitable result of our own weaknesses. What some call terrorism in our region is the cynical machinery of dressed in the trappings of extremism. But the real motivation of which lies in a covetousness for the significant resources that God has placed in our uh land."},{"t":436,"topic":"Niger uranium","text":"Nijair's uranium, Marley and Bkina Faso's gold, lithium, gas, oil and so many other riches still make the former colonial powers salivate. They want to make us believe that we are incapable of governing, of governing ourselves, incapable of producing, of thinking, and of defending ourselves. They want to make us believe and convince us that we do not have the science, the intelligence, or the sovereignty needed to build something precious by and for ourselves. and that as a consequence therefore we should accept the tutilage of Emanuel Macron's France and his allies a France which very often acts through its local proxies networks and complicity for centuries they have instilled self-deprecation fear and resignation they continue to want to introduce produce permanent conflict in communities which since time immemorial have been living in harmony in the same space and which have created peaceful mechanisms for settling disputes such as joking kinship for example."},{"t":519,"topic":"Sahel conflict","text":"This perfidious attempt to destabilize the central Sahel conducted by France with the active complicity of Ukraine is now documented widely documented. This criminal enterprise has been dismass has been unmasked now that the military, political and media elites that justify it in the name of their own country's interests have themselves removed their veils and and removed their masks. I say solemnly from this rostrm, the Sahel sees, the Sahel hears, the Sahel remembers, and the Sahel understands things very well. Our Sahel is determined to defend its liberty, its resources, and its dignity at any cost. A people that has decided to be free cannot be recolonized through fear, through deceit, nor even through savage violence."},{"t":589,"topic":"Niger security","text":"Ladies and gentlemen, as I speak to you on our northeastern border, there are proxies led by that France supported by Ukraine and two other And you know which countries I'm alluding to. Those proxies are armed, managed, and led and they are about to attack our military positions and our oil installations. &gt;&gt; But inshallah, they will find what they deserve if they do so. &gt;&gt; The AES, the result of a long and historic struggle of our peoples against colonization and neocolonialism. is now an irreversible process towards our country's sovereignty. Make no mistake, the century that we are living in marks the end of old hegemonies and the awakening of thus far suppressed forces."},{"t":659,"topic":"AES","text":"The AES is to Africa, its historic and contemporary diasporas, as light is to It is for this uh human community that is present around the world a source of hope and of dignity. And I say this before the world so that the world can understand. The AES is the result of a movement that dates from the dawn of time. It is a profound, lasting, irrepressible and irreversible change. A change which by trimming the sharp claws of imperialism, abolishing the trade in black persons and slavery, overthrowing colonialism and is bringing the peoples of Africa towards independence, sovereignty and I affirm that our reoundation in Nishair is not targeted against anyone."},{"t":729,"topic":"Niger sovereignty","text":"It is an expression of our will to rely on ourselves to have total control over our resources and also responsibility for our choices and our alliances. The head of state, President Tiani, has consistently said this. The only thing we are asking for is that we be left to manage our own destiny. We have never been driven out of a desire to trouble anyone else. So for us, it is simply a matter of moving towards the choice and supporting the choice that we have decided upon with our people behind us. Our organization must understand this truth. The sovereignty of our states is not negotiable. Our resources belong to our peoples. Our future will no longer be decided elsewhere. Ladies and gentlemen, this is an opportunity to commend the courage of our defense and security forces and to pay tribute to all of our civilian and military who have lost their lives in the struggle for our full and total liberty."},{"t":806,"topic":"Mali","text":"I bow down before their memory. May their souls rest in peace. I would also here &gt;&gt; like to commend the memory of the late General Sajio Kamada, Minister, Minister of Defense of Mali, whose ultimate sacrifice will forever be associated with the history of the Confederation of the States of the May Allah grant him eternal paradise. Ladies and gentlemen, we remain open to any security cooperation of course which takes into account our strategic interests, mutual interest and respect for our sovereignty with Bkinaaso and Mali. Nishair within the confederation of Sahal states is developing cooperation that is focused on defense and security diplomacy and This responds to a requirement for solidarity between peoples that face common challenges."},{"t":879,"topic":"Sahel integration","text":"On the 16th of September 2023 in Bamako, Nijair Mali Ambakina Faso signed the Liptako Gurma Charter giving birth to the alliance of Sahel states. On the 6th of July 2024 in Yame, our three heads of state, President Aimua of Mali, President Ibrahim Trare of and President Abdul Rahman Tani of Nijair took the historic step of creating the confederation of Sahil Two years later, the institutional structure of this confederation is practically complete. A unified force of 5,000 men is conducting the coordinated fight against the mercenaries afflicting our three uh on our borders. This force can be mobilized to a ceiling of 15,000 men."},{"t":940,"topic":"AES","text":"That must be underscored. A confederation investment and the development bank has been created. It finance our finances our projects and programs using our own resources. A confederation biometric passport has been in use since the 29th of January 2020 uh five. A television channel, a press agency, and a shared radio carry the voice and the message of the AES. More recently, from the 26th to the 29th of August the first meetings of the Confederation Parliament were held in Yam, thus completing our institutional Excellencies, ladies and gentlemen, Nijair is a country of peace. Truly a country of peace. It has never brought war and it will not bring war against another country. It is determined to defend itself and to control its natural resources."},{"t":1006,"topic":"Niger sovereignty","text":"It is very important for us to say this. We have chosen transformation that is based on national responsibility, making use of our resources, strengthening our institutions, and tangibly improving the living conditions of our citizens. Since the 26th of July 2023, Nijair has been continuing its inexurable march towards the total reconquest of its sovereignty under the leadership of the National Council for the Safeguarding of the Homeland by the President His Excellency the General of the Army Abdul Rahman Tiani, President of the Republic, head of state. This change is a radical break with the policies imposed from outside which were disconnected from the real needs of the population. It is rooted in the social values of the people of Aware of the challenges that it faces, the government, which I coordinate, has chosen to mobilize the necessary resources to finance agriculture and basic social sectors through funds from voluntary contributions of Ngerians In addition to revenues drawn from the exploitation of our mineral and oil resources, revenue which previously the state did not have control over."},{"t":1094,"topic":"Niger security","text":"Mr. President, ladies and gentlemen, a few days ago in the night from the 28th to the 29th of August 2026, after two previous fruitless attempts to attack Ji Hamani International Airport in Yame, a third attempt, which General Tiani said, a third attempt at destabilization led by obscurantist and colonialist forces targeted our institution. ions. As in the previous cases, it failed. It thanks to the loyalty of our forces, of our defense and security forces and the loyalty of our armed forces. It failed thanks to the solidarity of our allies and to the categorical refusal of the Nigerian people to go backwards. Nger emerges from this united and Investigations are underway."},{"t":1159,"topic":"Niger security","text":"The necessary investigations are underway in order to establish the circumstances, who is responsible, and the internal and external support linked to this attempt. Following that procedure, Nijer reserves the right in accordance with the United Nations Charter and international law to turn to and uh have recourse to the competent mechanisms to defend its In this regard, we ask that any concern a member state may have about their security be examined with haste and impartiality without differentiated treatment. The credibility of our organization, Mr. President, also depends on its ability to ensure that the voices of all of its member states are heard. You have a lot of work to do, Mr. President. Nijair is not pursuing confrontation with any country. It opens its arms to all partners that wish to build a new relationship based on equality, and mutual interest and shared interest."},{"t":1235,"topic":"Niger uranium","text":"Excellencies, ladies and gentlemen, for more than half a century, uranium, this this miraculous substance, Nijes uranium has lit the cities of Europe while our cities have remained in darkness. That injustice is now over. It is at an end. In June 2025, the state of Nijair recovered control of Somaya, the assoc associated delayer. Our resources will now be managed by us and for us and Nijair intends to sell its uranium on the international market in full transparency and in strict compliance with its nuclear non-prololiferation obligations. You will have heard at some point in the past uh France say that that Nija was intending to uh use this uranium."},{"t":1300,"topic":"Niger uranium","text":"When they left our country, they they sabotaged all of the material. Nijair has invested some 30 billion of our franks to continue that production. totally making use of nisharian workers and experts. Not a single foreigner was involved in that. &gt;&gt; The current stock belongs to our country. It does not belong to anyone and we will sell it to all those who wish to buy in total transparency as I have just said. Similarly, in 2024, our country became a an exporter of crude oil thanks to the oil pipeline linking Agadem to the Atlantic coast along the African cont the the longest one in the African continent making nijair one of the continent's fastest growing economies in That revenue is going into our own security to agriculture, electrification, and sanitation, education, health, uh the health of our fellow citizens."},{"t":1383,"topic":"Niger economy","text":"And the solidarity fund for the safeguarding of the homeland, which is um made up of the voluntary contributions of millions of Nigerians, tells you everything you need to know about a people that has understood that sovereignty has a price and that it is willing to pay it. Ladies and gentlemen, 3 years after breaking with the old order, progress on the ground is remarkable. Our economy has seen 7% growth in 2026 in 2025, excuse me, driven above all by oil and agriculture. Inflation, which reached 9.1% in 2024, has fallen to thanks uh to exceptional agricultural production and a targeted reduction of fuel and cement prices. All of the country's riches will be redistributed to benefit our population. The large scale irrigation program initiated by the president of the republic has 527 billion CFA franks and aims to ensure that around 22,000 hectares uh of new irrigated land can be established."},{"t":1461,"topic":"Niger development","text":"The results achieved in this regard are very satisfactory because for the first time in decades, our country has not faced food shortages or had to call upon foreign assistance. Through this program, we intend to have our grain imports by the end of 2027. on health we have reduced by 50% the cost of services in public health facilities. Some services are free. For example, child birth care for children uh aged 0 to 5 and dialysis. The assisted birth rate went from 36% in 2022 to 42.5% in 2025. and the rate of prenatal consultations went from 38% uh to it went from 32% to 38.2%. Education is free and mandatory for all children in public schools. What's more, a 20% reduction in school fees in private schools was decided upon in July These instructions that are contained in the program for the reoundation of the republic 2025 to 2029 make up the reference framework for all of the states actions in pursuit of the structural transformation of our These results are very encouraging despite the scale of the challenges because"},{"t":1552,"topic":"Niger resilience","text":"they are our results that we have achieved through our own means and resources. Excellencies, ladies and gentlemen, three years ago, some people predicted that Nijer would collapse under the weight of sanctions and isolation. Today, Nijair is standing It is standing tall because its people has refused to bow down. It is standing tall because within the confederation of Sahel states, it has found a family, solidarity, and a family in the full African meaning of the term. It is standing tall because the People's Democratic Republic of Algeria, a kindred and neighboring country, chose to support us with a substantial investment in the exploitation of our natural resources and through constant support for our defense system with We are also engaging in dynamic cooperation in the areas of health, education, energy, water, and On top of that, there are significant structural projects such as the tripartite gas pipeline and the transahara road."},{"t":1626,"topic":null,"text":"Asia is above all standing tall because it has regained possession of its land, what lies beneath the land and of its Mr. President, our country is also standing tall because it un because it is speaking within our shared organization, the UN, and because among its members, we countries with which we have fruitful cooperation based on mutual respect. And in this regard, allow me to say that Togo, Turka, the Kingdom of Morocco, the Russian and the People's Republic of China are among our friends. True friends. On behalf of the President of the Republic, the head of state, I would like to express our full gratitude to Mr. President, excellencies, ladies and gentlemen, Nishair remains faithful to the values included in its motto, fraternity, work and progress and to the values in the motto of our confederation."},{"t":1696,"topic":"Niger sovereignty","text":"One space, one people, one destiny. The security, development and dignity of our peoples cannot be envisaged separately. We have understood that and that is why we stand closely We believe in international relations rooted in cooperation, dignity, sovereignty, and mutual respect. We are convinced that no country, however powerful it may be, can claim to be the world's policeman. That time is To conclude, respects others choices and is not asking anyone to share our choices. We ask everyone to respect those choices. Nija intends to fully exercise its sovereignty over its natural resources and will never again accept any restriction imposed from outside on its sovereign right to freely choose its partners."},{"t":1761,"topic":"Sovereign equality","text":"That right is inalienable and it is non-negotiable. We declare that trust will be reborn when every nation big or small is treated with the same consideration. when the right to sovereign equality, to territorial integrity, to freely choose one's partners, and to when those rights are respected. This is the condition for restoring trust, for making transformation just and for the United Nations to truly provide results for all and for the United Nations to be respected by all and for the United Nations to ensure that it is respected and to ensure that everyone and believes it is an organization for all."},{"t":1830,"topic":"Sahel states","text":"Long live international cooperation. Long live the Confederation of Sahel States. Long live the Republic of Nijair. Ladies and gentlemen, thank you for your kind On behalf of the assembly, I wish to thank the prime minister of the Republic of Nigeria."}],"compare":[{"topic":"Niger","share":0.2932,"mean":0.0,"rank":1,"others":0},{"topic":"Africa","share":0.1837,"mean":0.0226,"rank":7,"others":36},{"topic":"Artificial Intelligence","share":0.0798,"mean":0.0503,"rank":48,"others":83},{"topic":"UN & its reform","share":0.0453,"mean":0.2056,"rank":168,"others":170},{"topic":"Mali","share":0.0429,"mean":0.0008,"rank":2,"others":1},{"topic":"International Law & Order","share":0.0404,"mean":0.0605,"rank":98,"others":102},{"topic":"Israel–Palestine","share":0.0373,"mean":0.0525,"rank":76,"others":76}]};
